-- Add InfoNCE, introduced in arXiv 1807.03748.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'infonce',
    'InfoNCE',
    'Info Noise-Contrastive Estimation (InfoNCE)',
    'InfoNCE is a contrastive loss introduced with Contrastive Predictive Coding (CPC). Given a context, a model must pick the one positive sample out of a set of N samples whose other N−1 entries are negatives, which amounts to a softmax cross-entropy over similarity scores. It is based on noise-contrastive estimation (NCE), and minimising it maximises a lower bound on the mutual information between the representation and the target, a bound that tightens as more negatives are used. In CPC an encoder maps inputs to latents, an autoregressive model summarises past latents into a context, and InfoNCE trains the context to predict future latents against negatives drawn from other time steps or sequences. This gave strong representations across speech, images, text and reinforcement learning in 3D environments. InfoNCE, and its temperature-scaled NT-Xent form, became the standard objective of [contrastive learning](/methods/contrastive-learning), underlying [SimCLR](/methods/simclr), [MoCo](/paper/1911.05722), [CLIP](/methods/clip) and dense retrieval models.',
    'InfoNCE, info-nce',
    (
        SELECT id
        FROM areas
        WHERE name = 'General'
        LIMIT 1
    ),
    2018,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '1807.03748'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Representation Learning with Contrastive Predictive Coding',
    NULL,
    NULL,
    '[Representation Learning with Contrastive Predictive Coding](/paper/1807.03748)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'infonce' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'infonce' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

