INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'infonce citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM infonce_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING infonce_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 54 local citers name the method in title or abstract.
CREATE TEMP TABLE infonce_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'infonce'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        9806, 10885, 12238, 12877, 13967, 13968, 14171, 15684, 17154, 18469, 19570, 20869,
        22062, 36462, 37103, 45115, 45572, 45852, 46994, 49011, 49713, 56364, 56767, 56846,
        57590, 61816, 65184, 67361, 67747, 67771, 69947, 71297, 71949, 73281, 77976, 78390,
        78449, 83957, 86032, 86219, 86644, 92175, 92319, 92962, 94437, 96760, 100025, 100142,
        100560, 100734, 102007, 108247, 108495, 113900
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM infonce_cited_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'reference' FROM infonce_cited_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

-- 89 papers match the method keywords (same matcher as the
-- daily keyword backfill).
CREATE TEMP TABLE infonce_keyword_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'infonce'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        4238, 4374, 6916, 7022, 7119, 7470, 8656, 9347, 9573, 9806, 10885, 12238,
        12877, 13967, 13968, 14171, 15684, 17154, 18469, 20869, 22062, 36462, 37103, 45115,
        45572, 45794, 45852, 46994, 47375, 48911, 49011, 49713, 56364, 56767, 56846, 57590,
        59657, 59954, 61816, 63309, 64664, 65036, 65184, 65582, 66329, 67361, 67747, 67771,
        69947, 69990, 70342, 70961, 71297, 71949, 73281, 77147, 78390, 78397, 78449, 80184,
        83769, 83957, 85016, 86032, 86219, 86644, 87849, 89192, 92175, 92319, 92962, 94381,
        94437, 94568, 96760, 96949, 100025, 100142, 100560, 100734, 102007, 102534, 102580, 107927,
        108247, 108495, 113900, 120789, 122949
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM infonce_keyword_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'keyword' FROM infonce_keyword_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();
